function api($method,$path,$user=null,$payload=null,$expected=200){$headers=['Accept: application/json','Content-Type: application/json'];if($user)$headers[]='Authorization: Bearer '.Tymon\JWTAuth\Facades\JWTAuth::fromUser($user);$c=curl_init('http://127.0.0.1:18084/api/'.$path);curl_setopt_array($c,[CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$headers,CURLOPT_TIMEOUT=>20]);if($payload!==null)curl_setopt($c,CURLOPT_POSTFIELDS,json_encode($payload));$raw=curl_exec($c);$status=curl_getinfo($c,CURLINFO_HTTP_CODE);curl_close($c);if($status!==$expected)throw new RuntimeException("$path expected $expected got $status $raw");$j=json_decode($raw,true);return $j['data']??$j;}
