$totp=app(App\Services\TotpService::class);$secret=$totp->generateSecret();$a->two_factor_secret=encrypt($secret);$a->two_factor_confirmed_at=now();$a->save();$challenge=api('POST','auth/login',null,['email'=>$a->email,'password'=>'Long-test-password!']);ok(!empty($challenge['twoFactorRequired']) && empty($challenge['token']),'two factor challenge does not issue access token');
